tool_input.new_string:
.navbar {
  position: relative;
  z-index: 9; /* 高于 TagsView(8)，避免下拉层延伸到标签栏区域时被盖住 */
  --navbar-brand-width: 250px;
  height: 110px;
  min-height: 110px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--menu-bg-color, rgb(5, 44, 80));
  padding-left: env(safe-area-inset-left);
  padding-right: env(safe-area-inset-right);
  box-sizing: border-box;
  min-width: 0;
  isolation: isolate;
}

.navbar::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(25, 90, 150, 0.74), rgba(25, 90, 150, 0.74)),
    url('/assets/images/navbar-bg.png');
  background-repeat: no-repeat;
  background-position: left bottom, left bottom;
  background-size: cover, cover;
  pointer-events: none;
  z-index: 0;
}

.navbar-sprite-host {
  position: absolute;
  z-index: 0;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}
